3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the {@code customerCode} in the form {@code <REGION>-<HASH8>}: REGION is the
12	 * region derived from the postcode (see {@link Locality}) and HASH8 is the first 8
13	 * upper-case hex characters of SHA-256 over the normalised telephone plus lastName.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner) {
18	        String region = Locality.of(owner.getCity(), owner.getPostcode());
19	        String hash8 = hash8(E164Telephone.toE164(owner.getTelephone()) + owner.getLastName());
20	        owner.setCustomerCode(region + "-" + hash8);
21	    }
22	
23	    private static String hash8(String value) {
24	        try {
25	            byte[] digest = MessageDigest.getInstance("SHA-256")
26	                .digest(value.getBytes(StandardCharsets.UTF_8));
27	            StringBuilder hex = new StringBuilder();
28	            for (int i = 0; i < 4; i++) {
29	                hex.append(String.format("%02X", digest[i]));
30	            }
31	            return hex.toString();
32	        } catch (NoSuchAlgorithmException ex) {
33	            throw new IllegalStateException(ex);
34	        }
35	    }
36	}
