1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Computes the {@code checkDigit}: a single Luhn check digit (0-9) over the digits
5	 * contained in the {@code customerCode} (e.g. {@code SMI-0007} → the Luhn digit of 0007).
6	 */
7	public final class CheckDigit {
8	
9	    private CheckDigit() {
10	    }
11	
12	    public static int of(String customerCode) {
13	        int sum = 0;
14	        boolean dbl = true;
15	        for (int i = customerCode.length() - 1; i >= 0; i--) {
16	            char c = customerCode.charAt(i);
17	            if (c < '0' || c > '9') {
18	                continue;
19	            }
20	            int d = c - '0';
21	            if (dbl) {
22	                d *= 2;
23	                if (d > 9) {
24	                    d -= 9;
25	                }
26	            }
27	            sum += d;
28	            dbl = !dbl;
29	        }
30	        return (10 - (sum % 10)) % 10;
31	    }
32	}
