1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.apache.commons.codec.language.Soundex;
9	
10	/**
11	 * Derives the single duplicate-detection key that consolidates the former separate
12	 * telephone, email and household checks. It is the SHA-256 hex over
13	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty
14	 * segment for an absent value. Telephone is already E.164-normalised and email lower-cased
15	 * by earlier steps, so two owners collide only when their whole key matches. The
16	 * {@code postcode} argument is retained for the mapper's stable call site but is not part of
17	 * the key.
18	 */
19	public final class IdentityKey {
20	
21	    private IdentityKey() {
22	    }
23	
24	    public static String of(String telephone, String email, String lastName, String postcode) {
25	        String raw = blankToEmpty(telephone) + '|'
26	                + blankToEmpty(email).toLowerCase(Locale.ROOT) + '|'
27	                + soundex(lastName);
28	        return sha256Hex(raw);
29	    }
30	
31	    /** Soundex of {@code lastName}, letters-only so the codec never rejects the input. */
32	    public static String soundex(String lastName) {
33	        String cleaned = lastName == null ? "" : lastName.replaceAll("[^A-Za-z]", "");
34	        return cleaned.isEmpty() ? "" : Soundex.US_ENGLISH.soundex(cleaned);
35	    }
36	
37	    private static String blankToEmpty(String value) {
38	        return value == null ? "" : value;
39	    }
40	
41	    private static String sha256Hex(String value) {
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
44	            StringBuilder sb = new StringBuilder(digest.length * 2);
45	            for (byte b : digest) {
46	                sb.append(String.format("%02x", b));
47	            }
48	            return sb.toString();
49	        }
50	        catch (NoSuchAlgorithmException e) {
51	            throw new IllegalStateException(e);
52	        }
53	    }
54	}
