5	/**
6	 * Derives the {@code ownerSegment} label {@code <TIER>_<AREA>}. TIER is {@code PREMIUM}
7	 * when membershipLevel is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO}
8	 * when the locality is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
9	 */
10	public final class OwnerSegment {
11	
12	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
13	
14	    private OwnerSegment() {
15	    }
16	
17	    public static String of(int membershipLevel, String locality) {
18	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
19	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
20	        return tier + "_" + area;
21	    }
