3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year helpers. The fiscal year starts on 1 July, so a date on or after 1 July
7	 * belongs to the fiscal year ending in the following calendar year. {@link #of} yields that
8	 * ending calendar year, {@link #label} formats it as {@code FY<YY>} (its last two digits),
9	 * and {@link #elapsed} counts whole fiscal years between two dates.
10	 */
11	public final class FiscalYear {
12	
13	    private FiscalYear() {
14	    }
15	
16	    public static int of(LocalDate date) {
17	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
18	    }
19	
20	    public static String label(LocalDate date) {
21	        return String.format("FY%02d", of(date) % 100);
22	    }
23	
24	    public static int elapsed(LocalDate from, LocalDate to) {
25	        return of(to) - of(from);
26	    }
27	}
