1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Converts a raw telephone number to E.164 form: strip spaces, dashes and brackets; keep
5	 * a leading '+' and country code when present, otherwise assume country code '+61' and
6	 * drop a single leading '0' from the national digits. Requires 8 to 15 digits after the
7	 * '+', and enforces the national-number length per country ('+61' needs 9 national
8	 * digits, '+1' needs 10). Returns {@code null} when no valid E.164 number can be formed.
9	 */
10	public final class E164Telephone {
11	
12	    private E164Telephone() {
13	    }
14	
15	    public static String toE164(String raw) {
16	        if (raw == null) {
17	            return null;
18	        }
19	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
20	        String digits;
21	        if (cleaned.startsWith("+")) {
22	            digits = cleaned.substring(1);
23	        } else {
24	            if (cleaned.startsWith("0")) {
25	                cleaned = cleaned.substring(1);
26	            }
27	            digits = "61" + cleaned;
28	        }
29	        // '+61' needs 9 national digits and '+1' 10 — each a total of 11 digits.
30	        boolean countryCoded = digits.startsWith("61") || digits.startsWith("1");
31	        return digits.matches("\\d{8,15}") && (!countryCoded || digits.length() == 11)
32	                ? "+" + digits : null;
33	    }
34	}
