7	
8	/**
9	 * Flags a soft duplicate before the new owner is saved. A hard duplicate (matching
10	 * {@link IdentityKey}) has already been rejected by {@link RequireUniqueIdentity}; this
11	 * records the id of an existing owner whose {@code soundex(lastName)} and postcode match but
12	 * whose identity key differs, so the response can surface {@code possibleDuplicate}/
13	 * {@code possibleDuplicateOf}. A declared household member ({@code sharesHousehold}) is not
14	 * a suspected duplicate, and there is no match when there is no postcode. */
15	public class DetectPossibleDuplicate {
16	
17	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
18	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
19	            return;
20	        }
21	        String postcode = owner.getPostcode();
22	        if (postcode == null || postcode.isBlank()) {
23	            return;
24	        }
25	        String soundex = IdentityKey.soundex(owner.getLastName());
26	        String key = keyOf(owner);
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (existing.isDeleted()) {
29	                continue;
30	            }
31	            if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
32	                    && postcode.equals(existing.getPostcode()) && !key.equals(keyOf(existing))) {
33	                owner.setPossibleDuplicateOf(existing.getId());
34	                return;
35	            }
36	        }
37	    }
38	
39	    private static String keyOf(Owner owner) {
40	        return IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName(),
41	                owner.getPostcode());
42	    }
43	}
